// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title GRPCRateLimiter
 * @notice On-chain rate limiting for cross-service gRPC authentication tokens
 * @dev Services submit signed attestations; contract enforces per-epoch rate limits
 */
contract GRPCRateLimiter {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct ServiceConfig {
        address signer;
        uint256 maxRequestsPerEpoch;
        uint256 epochDuration;
        bool active;
    }

    struct EpochState {
        uint256 requestCount;
        uint256 epochStart;
    }

    mapping(bytes32 => ServiceConfig) public services;
    mapping(bytes32 => mapping(uint256 => EpochState)) public epochStates;
    mapping(bytes32 => uint256) public currentEpochId;
    mapping(bytes32 => mapping(bytes32 => bool)) public usedNonces;

    address public admin;
    uint256 public globalCooldown;
    mapping(bytes32 => uint256) public lastRequestTimestamp;

    event RequestProcessed(bytes32 indexed serviceId, uint256 epochId, uint256 count);
    event EpochRotated(bytes32 indexed serviceId, uint256 newEpochId);
    event ServiceRegistered(bytes32 indexed serviceId, address signer);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    constructor(uint256 _globalCooldown) {
        admin = msg.sender;
        globalCooldown = _globalCooldown;
    }

    function registerService(
        bytes32 serviceId,
        address signer,
        uint256 maxRequests,
        uint256 epochDuration
    ) external onlyAdmin {
        require(!services[serviceId].active, "Already registered");
        require(signer != address(0), "Invalid signer");
        services[serviceId] = ServiceConfig({
            signer: signer,
            maxRequestsPerEpoch: maxRequests,
            epochDuration: epochDuration,
            active: true
        });
        epochStates[serviceId][0] = EpochState({
            requestCount: 0,
            epochStart: block.timestamp
        });
        emit ServiceRegistered(serviceId, signer);
    }

    function _rotateEpochIfNeeded(bytes32 serviceId) internal returns (uint256) {
        uint256 epochId = currentEpochId[serviceId];
        EpochState storage state = epochStates[serviceId][epochId];
        ServiceConfig storage config = services[serviceId];

        if (block.timestamp >= state.epochStart + config.epochDuration) {
            epochId += 1;
            currentEpochId[serviceId] = epochId;
            epochStates[serviceId][epochId] = EpochState({
                requestCount: 0,
                epochStart: block.timestamp
            });
            emit EpochRotated(serviceId, epochId);
        }
        return epochId;
    }

    function _verifyServiceAttestation(
        bytes32 serviceId,
        bytes32 nonce,
        uint256 timestamp,
        bytes memory signature
    ) internal view returns (bool) {
        ServiceConfig storage config = services[serviceId];
        bytes32 messageHash = keccak256(
            abi.encodePacked(serviceId, nonce, timestamp, address(this))
        );
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);
        return recovered == config.signer;
    }

    function _enforceGlobalCooldown(bytes32 serviceId) internal {
        require(
            block.timestamp >= lastRequestTimestamp[serviceId] + globalCooldown,
            "Global cooldown active"
        );
        lastRequestTimestamp[serviceId] = block.timestamp;
    }

    function _checkRateLimit(bytes32 serviceId, uint256 epochId) internal view returns (bool) {
        EpochState storage state = epochStates[serviceId][epochId];
        ServiceConfig storage config = services[serviceId];
        return state.requestCount < config.maxRequestsPerEpoch;
    }

    function _incrementCounter(bytes32 serviceId, uint256 epochId) internal {
        epochStates[serviceId][epochId].requestCount += 1;
    }

    /**
     * @notice Submit authenticated gRPC request attestation
     * @param serviceId The service identifier
     * @param nonce Unique nonce to prevent replay
     * @param timestamp Request timestamp (must be within 5 min)
     * @param signature ECDSA signature from service key
     * @param batchSize Number of requests in this batch (for batch processing)
     */
    function submitRequest(
        bytes32 serviceId,
        bytes32 nonce,
        uint256 timestamp,
        bytes calldata signature,
        uint256 batchSize
    ) external returns (bool) {
        require(services[serviceId].active, "Service not active");
        require(!usedNonces[serviceId][nonce], "Nonce already used");
        require(
            block.timestamp <= timestamp + 300 && block.timestamp >= timestamp,
            "Timestamp out of range"
        );

        // Verify the cross-service authentication signature
        require(
            _verifyServiceAttestation(serviceId, nonce, timestamp, signature),
            "Invalid attestation"
        );

        // Mark nonce as used
        usedNonces[serviceId][nonce] = true;

        // Enforce global cooldown between requests
        _enforceGlobalCooldown(serviceId);

        // Rotate epoch if needed and get current epoch
        uint256 epochId = _rotateEpochIfNeeded(serviceId);

        // Check rate limit accounting for the full batch
        EpochState storage state = epochStates[serviceId][epochId];
        ServiceConfig storage config = services[serviceId];
        require(
            state.requestCount + batchSize <= config.maxRequestsPerEpoch,
            "Rate limit exceeded"
        );

        // Increment by batchSize to account for batched gRPC calls
        state.requestCount += batchSize;

        emit RequestProcessed(serviceId, epochId, state.requestCount);
        return true;
    }

    function getRemainingRequests(bytes32 serviceId) external view returns (uint256) {
        uint256 epochId = currentEpochId[serviceId];
        EpochState storage state = epochStates[serviceId][epochId];
        ServiceConfig storage config = services[serviceId];
        if (state.requestCount >= config.maxRequestsPerEpoch) return 0;
        return config.maxRequestsPerEpoch - state.requestCount;
    }

    function getEpochInfo(bytes32 serviceId) external view returns (
        uint256 epochId,
        uint256 requestCount,
        uint256 epochStart,
        uint256 epochEnd
    ) {
        epochId = currentEpochId[serviceId];
        EpochState storage state = epochStates[serviceId][epochId];
        ServiceConfig storage config = services[serviceId];
        return (
            epochId,
            state.requestCount,
            state.epochStart,
            state.epochStart + config.epochDuration
        );
    }
}
